mapper.select:
SELECT gu.*, u.user_name, u.avatar, u.phone, gi.`name` as groupInfoName FROM travel_group_user gu LEFT JOIN travel_group_info gi ON gu.group_info_id = gi.id LEFT JOIN tb_user u ON gu.user_id = u.user_id
and gu.user_id = #{param.userId}
and u.user_name like concat('#', #{param.userName} ,'#')
and gu.group_info_id = #{param.groupInfoId}
and gi.name like concat('#', #{param.groupInfoName} ,'#')
and gu.status = #{param.status}
order by gu.create_time desc
